function scsv(rows){return rows.map(row=>row.map(v=>{let value=String(v??'');if(typeof v==='string'&&/^[=+@-]/.test(value))value="'"+value;return '"'+value.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
