 $('#nav').innerHTML='<div class="brand"><span class="mk">C</span>ClickLab</div><div class="studio-eyebrow" style="padding-left:12px">CREATOR WORKSPACE</div>'+groups.map(([name,ids])=>'<div class="grp">'+name+'</div>'+ids.map(id=>'<a href="#/'+id+'" data-v="'+id+'" class="'+(view===id?'on':'')+'" '+(view===id?'aria-current="page"':'')+'>'+ico(VW[id].i,17)+sx(VW[id].t)+'</a>').join('')).join('')+
 '<details class="nav-context"><summary>Active scans & channels</summary><select id="csel" aria-label="Active channel"><option value="">Choose channel</option>'+SCANS.filter(s=>s.kind==='channel').map(s=>'<option value="'+sx(s.id)+'" '+(s.id===cur?'selected':'')+'>'+sx(s.ch?.name||s.topic)+'</option>').join('')+'</select><select id="sel" aria-label="Active topic"><option value="">Choose topic</option>'+SCANS.filter(s=>s.kind==='topic').map(s=>'<option value="'+sx(s.id)+'" '+(s.id===cur?'selected':'')+'>'+sx(s.topic)+'</option>').join('')+'</select><button class="sm" onclick="goNewChan()">New channel scan</button></details><div class="navfoot"><a href="#/gen" data-v="gen">'+ico('gear',16)+'Settings & API keys</a><a href="#/help" data-v="help">'+ico('help',16)+'Help</a></div>';
