 $('#main').innerHTML='<button class="sm gh" onclick="ST.tool=null;toolsv()">← All tools</button><div class="studio-eyebrow" style="margin-top:24px">'+sx(t.category)+' / '+sx(toolSource(t))+'</div><h2>'+sx(t.name)+'</h2><p class="sub">'+sx(t.description)+'</p><div class="studio-workbench"><section class="card"><h3>01 &nbsp; Your input</h3><form class="studio-form" id="studio-form" onsubmit="event.preventDefault();toolRun()">'+inputs+'<button id="tool-run" class="go" '+(ST.busy?'disabled':'')+'>'+(ST.busy?'Working…':t.mode==='ai'?'Generate draft':'Run tool')+'</button><button type="button" class="sm gh" onclick="toolSaveDraft()">Save input locally</button></form><p class="studio-muted" style="font-size:11px;margin:18px 0 0">'+sx(t.mode==='ai'?'Uses the configured text AI provider. Your supplied text is sent to that provider.':toolSource(t)==='Local utility'?'Runs locally; image files stay in your browser.':'Uses your configured YouTube API key. Provider errors and coverage limits are shown.')+'</p></section><section class="card"><div class="live-head"><h3>02 &nbsp; Your result</h3><div class="bar"><button class="sm" onclick="toolCopy()">Copy</button><button class="sm" onclick="toolExport()">Export</button></div></div><div id="tool-result" aria-live="polite">'+sempty('Ready when you are','Add your input and run the tool. Your result will appear here.')+'</div></section></div>';
 try{const d=JSON.parse(localStorage.getItem('cl_tool_draft_'+id)||'{}');for(const [k,v] of Object.entries(d)){const e=document.getElementById(k);if(e&&e.type!=='file')e.value=v}}catch(e){}
