async function betterFetch(vid,title){
 if(!vid)return toast('No video ID available','warn');
 if(!confirm('Confirm: this is your video or you have permission/licence to edit it. Fetch it into Analyze & Edit?'))return;
 toast('Fetching video locally…','ok');
 try{const r=await jp('/api/media-import',{rights:true,vid,quality:'1080'});if(r.error)throw Error(r.error);sessionStorage.setItem('cl_better_import',JSON.stringify({token:r.token,name:r.name||title||'video.mp4'}));location.hash='#/tools/smart-edit'}catch(e){toast(e.message,'bad')}
}
function startAutoEdit(vid,title){if(!confirm('Confirm: this is your video or you have permission/licence to edit it. Click OK to create a standard colour/audio polish export.'))return;const a=document.createElement('a');a.href='/api/auto-edit?vid='+encodeURIComponent(vid)+'&title='+encodeURIComponent(title);a.download='';a.click()}
function mediaEditButton(){return '<button class="sm media-edit-button" type="button" onclick="event.preventDefault();event.stopPropagation();location.hash=\'#/tools/video-edit\'">Edit own copy</button>'}
function mediaDownloadDialog(vid,title){if(!vid)return toast('No video ID available','warn');const old=$('#media-download-dialog');if(old)old.remove();const safe=sx(title||'video');document.body.insertAdjacentHTML('beforeend','<div id="media-download-dialog" class="studio-modal"><div class="studio-modal-card"><button class="studio-modal-close" onclick="$(\'#media-download-dialog\').remove()" aria-label="Close">×</button><div class="studio-eyebrow">MEDIA DOWNLOAD</div><h3>'+safe+'</h3><p class="studio-muted">Download only content you own or have permission to use. YouTube terms and creator rights still apply.</p><div class="studio-form"><label>Type<select id="media-kind" onchange="mediaQualityOptions()"><option value="video">Video</option><option value="audio">Audio</option></select></label><label>Quality<select id="media-quality"></select></label><label>Format<select id="media-format"></select></label><button class="go" onclick="startMediaDownload(\''+sx(vid)+'\',\''+safe.replaceAll("'","&#39;")+'\')">Download</button></div><p id="media-download-status" class="studio-muted" aria-live="polite"></p></div></div>');mediaQualityOptions()}
function mediaQualityOptions(){const e=$('#media-quality'),f=$('#media-format'),kind=$('#media-kind')?.value;if(!e||!f)return;if(kind==='audio'){e.innerHTML='<option value="128">128 kbps · smaller</option><option value="192">192 kbps · balanced</option><option value="320">320 kbps · highest</option>';f.innerHTML='<option value="mp3">MP3</option><option value="wav">WAV</option><option value="m4a">M4A</option><option value="flac">FLAC</option><option value="opus">Opus</option>'}else{e.innerHTML='<option value="best">Best available</option><option value="1080">1080p · Full HD</option><option value="720">720p · HD</option><option value="480">480p</option><option value="360">360p · smaller</option>';f.innerHTML='<option value="mp4">MP4</option><option value="webm">WebM</option><option value="mkv">MKV</option>'}}
function startMediaDownload(vid,title){const kind=$('#media-kind').value,quality=$('#media-quality').value,format=$('#media-format').value,status=$('#media-download-status');status.textContent='Preparing '+kind+' download…';const url='/api/media-download?vid='+encodeURIComponent(vid)+'&kind='+encodeURIComponent(kind)+'&quality='+encodeURIComponent(quality)+'&format='+encodeURIComponent(format)+'&title='+encodeURIComponent(title);const a=document.createElement('a');a.href=url;a.download='';a.click();setTimeout(()=>{status.textContent='Download started. If the browser blocks it, use the link again and allow downloads.'},700)}
function table(headers,rows){return '<div class="studio-scroll"><table class="studio-table"><thead><tr>'+headers.map(x=>'<th>'+sx(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+sx(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function readDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read the selected video.'));r.readAsDataURL(file)})}
async function runBetterSmartEdit(){
 betterProgress(0);
 if(!$('#sf-rights')?.checked)throw Error('Confirm that you own this video or have a licence to edit it.');
 let imported=null;try{imported=JSON.parse(sessionStorage.getItem('cl_better_import')||'null')}catch(e){}
 const file=$('#sf-video-file')?.files?.[0];
 const youtubeUrl=$('#sf-youtube-url')?.value?.trim()||'';
 const quality=$('#sf-quality')?.value||'1080';
 if(!file&&!imported?.token&&!youtubeUrl)throw Error('Upload a video, paste a YouTube link, or use Better beside a video card.');
 if(file&&file.size>1024*1024*1024)throw Error('Video is larger than 1 GB.');
 if(BETTER_MEDIA.original)URL.revokeObjectURL(BETTER_MEDIA.original);
 if(BETTER_MEDIA.output)URL.revokeObjectURL(BETTER_MEDIA.output);
 BETTER_MEDIA={original:null,output:null};
 betterProgress(1);
 if(!imported?.token&&youtubeUrl){const ir=await jp('/api/media-import',{rights:true,url:youtubeUrl,quality});if(ir.error)throw Error(ir.error);imported=ir}
 if(imported?.token){const pr=await fetch('/api/media-preview?token='+encodeURIComponent(imported.token));if(!pr.ok)throw Error('Fetched video preview expired. Fetch it again.');BETTER_MEDIA.original=URL.createObjectURL(await pr.blob())}
 else BETTER_MEDIA.original=URL.createObjectURL(file);
 const preset=$('#sf-preset')?.value||'better2';
 const base=imported?.token?{rights:true,import_token:imported.token,quality,preset,mirror:!!$('#sf-mirror')?.checked,transcribe:!!$('#sf-transcribe')?.checked,silence:!!$('#sf-silence')?.checked}:{rights:true,b64:await readDataURL(file),name:file.name,quality,preset,mirror:!!$('#sf-mirror')?.checked,transcribe:!!$('#sf-transcribe')?.checked,silence:!!$('#sf-silence')?.checked};
 if($('#sf-execution')?.value==='modal')return await runModalBetterEdit(base)
 betterProgress(2);
 const analysis=await jp('/api/media-analyze',base); if(analysis.error)throw Error(analysis.error);
 betterProgress(3);
 const liveTimer=setInterval(()=>{const el=$('#tool-result .studio-chip'),bar=$('#tool-result i');if(!el||!bar)return;const n=Math.min(94,78+Math.floor((Date.now()%120000)/750));el.textContent=n+'%';bar.style.width=n+'%'},750);
 const exportResult=await jp('/api/better-edit',base); clearInterval(liveTimer); if(exportResult.error)throw Error(exportResult.error);
 if(exportResult.output_token){const op=await fetch('/api/media-preview?token='+encodeURIComponent(exportResult.output_token));if(!op.ok)throw Error('Better export preview expired. Run it again.');BETTER_MEDIA.output=URL.createObjectURL(await op.blob())}
 else if(exportResult.base64){const bin=atob(exportResult.base64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);BETTER_MEDIA.output=URL.createObjectURL(new Blob([bytes],{type:'video/mp4'}));}
 if(imported?.token)sessionStorage.removeItem('cl_better_import');
 betterProgress(4);
 setTimeout(()=>decorateBetterDownload(exportResult),0);
 return {...exportResult,analysis};
}
function betterProgress(stage){const preset=$('#sf-preset')?.value==='better'?'Better Polish':'Better 2.0',labels=['Preparing input','Loading original preview','Analysing video','Applying '+preset+' FFmpeg preset','Finalising comparison'],pct=[8,20,45,78,100][stage]||100,q=$('#sf-quality')?.value||'1080';const h=labels.map((x,i)=>'<div style="display:flex;gap:10px;align-items:center;margin:9px 0"><span style="width:22px;height:22px;border-radius:50%;display:inline-grid;place-items:center;background:'+(i<stage?'var(--accent)':i===stage?'var(--tx)':'var(--line)')+';color:'+(i<=stage?'#08110e':'var(--muted)')+';font-size:12px">'+(i<stage?'✓':i+1)+'</span><span style="color:'+(i<=stage?'var(--tx)':'var(--muted)')+'">'+x+(i===stage?' · working…':i<stage?' · complete':' · pending')+'</span></div>').join('');if($('#tool-result'))$('#tool-result').innerHTML='<div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h3>'+preset+' progress</h3><span class="studio-chip">'+pct+'%</span></div><p class="studio-muted">Target quality: '+q+'p</p>'+h+'<div style="height:9px;background:var(--line);border-radius:99px;overflow:hidden;margin-top:16px"><i style="display:block;height:100%;width:'+pct+'%;background:var(--accent);transition:width .3s"></i></div><p class="studio-muted" style="margin-bottom:0">'+(stage>=4?'Complete — comparison is ready.':'Please keep this window open while local processing runs.')+'</p></div>'}
async function toolRun(){if(ST.busy)return;const t=STUDIO_TOOLS.find(x=>x.id===ST.tool);if(!t)return;ST.busy=true;const id=t.id;ST.result=null;const button=$('#tool-run');button.disabled=true;button.textContent='Working…';$('#tool-result').innerHTML=sempty('Working on your request','Reading real data or processing your input. This can take longer for transcripts and AI.');
 try{let r;if(t.mode==='calc')r=calculateTool(t.id);else if(t.mode==='local')r=localTool(t.id);else if(t.mode==='rates')r=ratesTool();else if(['image','preview'].includes(t.mode))r=await imageTool(t);else if(t.mode==='checklist'){renderChecklist();r={source:'Local checklist',note:'Saved in this browser'}}else if(t.mode==='smart-edit')r=await runBetterSmartEdit();else{
 let q=svalue('q');if(!q.trim()&&t.mode!=='trending'&&!(t.mode==='topic-ideas'&&svalue('preset')))throw Error('Add your input first.');let mode=t.id==='trending-words'?'trending-keywords':t.mode;
 if(mode==='ai'&&['summary','chapters'].includes(id)&&extractVideo(q)){const tr=await jp('/api/studio/tool',{kind:'transcript',q});if(tr.error)throw Error(tr.error);if(!tr.text)throw Error('No transcript available. Paste your own transcript.');q=tr.text}
 r=await jp('/api/studio/tool',{kind:mode,q,task:t.name,region:svalue('region')||'US',language:svalue('language')||'en',keywords:svalue('keywords'),days:Number(svalue('days')||0),count:Number(svalue('count')||50),preset:svalue('preset'),category:svalue('category'),subniche:svalue('subniche'),niche:t.mode==='notebook'?NOTEBOOK_FLOW.niche:svalue('niche'),style:t.mode==='notebook'?NOTEBOOK_FLOW.style:'',keyword:t.mode==='notebook'?(NOTEBOOK_FLOW.focus?'':NOTEBOOK_FLOW.main):'',focus:t.mode==='notebook'?NOTEBOOK_FLOW.focus:'',shorts:id==='short-outliers',multiplier:Number(svalue('multiplier')||2)});
 if(r.error)throw Error(r.error);if(mode==='comments')ST.comments=r.rows||[];
 }
 if(ST.tool!==id)return;ST.result=r;if(t.mode!=='checklist')renderToolResult(t,r);
 }catch(e){if(ST.tool===id)$('#tool-result').innerHTML='<div class="err">'+sx(e.message)+'</div>'+snote('No successful result was produced. Check your input, API settings or provider availability, then retry.');}
 finally{ST.busy=false;const b=$('#tool-run');if(b){b.disabled=false;b.textContent='Run tool'}}}
function copyNotebookUrls(){if(ST.result?.url_text)cpText(ST.result.url_text)}
function notebookMetadataText(){const rows=ST.result?.rows||[];const header=['CLICKLAB NOTEBOOK — EASY METADATA REPORT','Search tip: find VIDEO 01, ORIGINAL TAGS / KEYWORDS, or COMPLETE DESCRIPTION.','Tags and keywords are the exact public uploader tags returned by YouTube; no title-based guesses.',''];return header.concat(rows.map((v,i)=>['==============================','VIDEO '+String(i+1).padStart(2,'0'),'==============================','TITLE: '+(v.title||'(untitled)'),'VIDEO URL: '+(v.video_url||'(missing)'),'CHANNEL: '+(v.channel||'(unknown)'),'CHANNEL URL: '+(v.channel_url||'(missing)'),'VIEWS: '+notebookViews(v.views),'DURATION (seconds): '+(v.seconds??'(unknown)'),'PUBLISHED: '+(v.published||'(unknown)'),'','ORIGINAL TAGS / KEYWORDS:',((v.tags||[]).join(', ')||'(none attached by uploader)'),'','COMPLETE DESCRIPTION:',v.description||'(empty)',''].join('\n'))).join('\n');}
