function downloadNotebookMetadata(){const t=notebookMetadataText();if(t)sdownload('notebook-metadata-easy.txt',t)}
async function downloadNotebookThumbnails(){const rows=(ST.result?.rows||[]).map(v=>({title:v.title,thumbnail:v.thumbnail}));if(!rows.length)return;try{const r=await fetch('/api/notebook-thumbnails',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows})});if(!r.ok)throw Error('Thumbnail ZIP could not be created');const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='notebook-thumbnails-HQ.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);toast('HQ thumbnail ZIP download started','ok')}catch(e){toast(e.message,'bad')}}
function decorateNotebookMetadata(r){const el=$('#tool-result'),bar=el?.querySelector('.studio-toolbar');if(!el||!bar)return;bar.insertAdjacentHTML('beforeend','<span class="notebook-export-label">Downloads:</span><button id="notebook-copy-meta">Copy easy metadata</button><button id="notebook-download-meta">Download easy metadata .txt</button><button id="notebook-download-thumbs">Download HQ thumbnails .zip</button>');$('#notebook-copy-meta').onclick=copyNotebookMetadata;$('#notebook-download-meta').onclick=downloadNotebookMetadata;$('#notebook-download-thumbs').onclick=downloadNotebookThumbnails;el.insertAdjacentHTML('afterbegin','<p class="notebook-metadata-help"><b>Metadata guide:</b> cards ke andar <b>Original tags & complete description</b> kholo. TXT mein har video ka block hai: TITLE → URL → ORIGINAL TAGS / KEYWORDS → COMPLETE DESCRIPTION.</p>');el.querySelectorAll('article.card').forEach((card,i)=>{const v=r.rows?.[i];if(!v)return;const tags=(v.tags||[]).join(', ')||'(none attached by uploader)';card.insertAdjacentHTML('beforeend','<details style="padding:0 14px 14px"><summary>Original tags & complete description</summary><p class="studio-muted"><b>Original tags / keywords:</b> '+sx(tags)+'</p><div class="studio-output">'+sx(v.description||'(empty)')+'</div></details>')})}
function notebookViews(v){const n=Number(v||0);if(n>=1e9)return (n/1e9).toFixed(n>=1e10?0:1).replace(/\.0$/,'')+'B';if(n>=1e6)return (n/1e6).toFixed(n>=1e7?0:1).replace(/\.0$/,'')+'M';if(n>=1e3)return (n/1e3).toFixed(n>=1e5?0:1).replace(/\.0$/,'')+'K';return String(n)}
