function median(a){if(!a.length)return null;const b=a.slice().sort((x,y)=>x-y),m=Math.floor(b.length/2);return b.length%2?b[m]:(b[m-1]+b[m])/2}
function calculateTool(id){const n=sNumber;let rows=[],note='Calculated from your supplied inputs. No external earnings or private Studio data is inferred.';const ratio=(a,b)=>{if(!b)throw Error('The denominator must be greater than zero.');return a/b};
 if(id==='money'){const views=n('views'),low=n('rpm-low'),high=n('rpm-high');if(high<low)throw Error('High RPM must be at least low RPM.');rows=[['Estimated low revenue ($)',views/1000*low],['Estimated high revenue ($)',views/1000*high]]}
 if(id==='engagement')rows=[['Engagement rate (%)',ratio(n('likes')+n('comments'),n('views'))*100]];
 if(id==='valuation'){if(n('high')<n('low'))throw Error('High multiple must be at least low multiple.');rows=[['Low valuation scenario ($)',n('profit')*n('low')],['High valuation scenario ($)',n('profit')*n('high')]];note='Scenario only. Multiples are your assumptions, not a verified market price or guaranteed sale.'}
 if(id==='monetization'){const subs=n('subs'),hours=n('hours'),shorts=n('shorts');rows=[['Subscribers remaining to 1,000',Math.max(0,1000-subs)],['Hours remaining to 4,000',Math.max(0,4000-hours)],['Shorts views remaining to 10M',Math.max(0,1e7-shorts)],['Numerical ad-revenue threshold met?',subs>=1000&&(hours>=4000||shorts>=1e7)?'Yes, based on supplied figures':'No']];note='Ad-revenue entry thresholds checked 9 Nov 2026: 1,000 subscribers plus 4,000 qualified public hours in 12 months OR 10M qualified Shorts views in 90 days. This does not verify policy eligibility, geography or approval. Check YouTube Studio Earn.'}
 if(id==='pay-view')rows=[['Estimated dollars per view',n('rpm')/1000],['Estimated revenue ($)',n('views')*n('rpm')/1000]];
 if(id==='sponsor'){if(n('high')<n('low'))throw Error('High CPM must be at least low CPM.');rows=[['Low fee scenario ($)',n('views')/1000*n('low')],['High fee scenario ($)',n('views')/1000*n('high')]];note='Negotiation scenario using your CPM assumptions; excludes rights, exclusivity and production costs.'}
 if(id==='watch-time'){const per=n('views')*n('minutes')/60,need=Math.max(0,n('target')-n('current'));rows=[['Modelled watch hours / month',per],['Hours remaining',need],['Months at constant pace',per?need/per:'No positive viewing pace']];note='Projection, not a forecast. Qualification and rolling 12-month expiry can change progress; Shorts-feed watch time does not count toward long-form qualified hours.'}
 if(id==='rpm')rows=[['RPM ($ / 1,000 views)',ratio(n('revenue'),n('views'))*1000],['CPM ($ / 1,000 ad impressions)',ratio(n('spend'),n('impressions'))*1000]];
 if(id==='outlier-score'){const raw=svalue('q').split(/[\s,]+/).filter(Boolean);const b=raw.map(Number);if(b.length<3||b.some(x=>!Number.isFinite(x)||x<0))throw Error('Enter at least 3 nonnegative baseline view counts.');const m=median(b);rows=[['Baseline sample',b.length],['Median baseline views',m],['Multiplier',ratio(n('views'),m)]];note='Use comparable videos of similar format and age. This is an observed ratio, not proof that the topic caused performance.'}
 if(id==='take-home'){if(n('tax')>100)throw Error('Tax reserve cannot exceed 100%.');const profit=n('gross')-n('expenses');rows=[['Profit before reserve ($)',profit],['Tax reserve ($)',Math.max(0,profit)*n('tax')/100],['After reserve ($)',profit-Math.max(0,profit)*n('tax')/100]];note='Arithmetic planning tool using your reserve rate, not a tax determination.'}
 if(id==='income'){const pairs=['ads','sponsors','members','other'].map(k=>[k,n(k)]);const total=pairs.reduce((s,p)=>s+p[1],0);rows=[['Total ($)',total],...pairs.map(([k,v])=>[k+' share (%)',total?v/total*100:0])]}
 if(id==='quota'){const mins=n('minutes');if(mins<1)throw Error('Tracking interval must be at least one minute.');const tracking=Math.ceil(1440/mins)*n('channels')*3;rows=[['Search calls / day (separate bucket)',n('searches')],['Other read units + tracking / day',n('reads')+tracking],['Tracking units / day (3 reads per channel poll)',tracking]];note='Planning estimate based on official quota documentation checked 9 Nov 2026: default 100 search calls/day in a separate bucket; 10,000 units/day for other endpoints. Retries and additional pages cost more. Confirm actual project quotas in Google Cloud.'}
 return {source:'Local calculation',rows:rows,html:table(['Metric','Result'],rows.map(([k,v])=>[k,typeof v==='number'?sn(v):v])),note};}
function ratesTool(){const rows=svalue('q').split('\n').filter(x=>x.trim()).map(line=>{const parts=line.split(',').map(x=>x.trim());if(parts.length!==3||!parts[0]||!parts[1]||!Number.isFinite(Number(parts[2]))||Number(parts[2])<0)throw Error('Each row must be: niche, country, nonnegative RPM');return [parts[0],parts[1],Number(parts[2])]});if(!rows.length)throw Error('Enter at least one assumption row.');const views=sNumber('views');return {source:'Your supplied RPM scenarios',rows,html:table(['Niche','Country','Assumed RPM ($)','Modelled revenue ($)'],rows.map(([n,c,r])=>[n,c,sn(r),sn(views/1000*r)])),note:'YouTube does not publish universal niche/country RPM tables. These are your inputs, not verified channel earnings.'}}
function extractVideo(value){const q=String(value||'').trim();if(/^[\w-]{11}$/.test(q))return q;try{const u=new URL(q.startsWith('http')?q:'https://'+q);let id='';if(['youtu.be','www.youtu.be'].includes(u.hostname))id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname))id=u.searchParams.get('v')||(/^\/(shorts|embed|live)\//.test(u.pathname)?u.pathname.split('/')[2]:'');return /^[\w-]{11}$/.test(id||'')?id:null}catch(e){return null}}
function localTool(id){const q=svalue('q').trim();if(!q)throw Error('Enter your input.');let html='',data={};
 if(id==='rights-edit'){const checks=[['You own the footage or have a written licence',!!$('#ef-rights-owned')?.checked],['Your edit adds commentary, education, reporting or another clear purpose',!!$('#ef-purpose')?.checked],['Third-party music is replaced or licensed',!!$('#ef-music')?.checked],['Source and licence records are saved',!!$('#ef-records')?.checked]];const plan=[['Cutting','Remove dead air and keep only clips needed for the new story'],['Pacing','Use deliberate cuts, reframing or b-roll to support your commentary'],['Colour','Correct exposure and white balance; grade for a consistent look'],['Audio','Level speech, reduce noise and use licensed music at a controlled level'],['Accessibility','Add accurate captions and check names, claims and context'],['Export','Keep the original project and export a normal H.264/AAC master']];data={checks,plan};html=table(['Check','Status'],checks.map(([k,v])=>[k,v?'Ready':'Needs action']))+'<h3>Suggested edit plan</h3>'+table(['Area','Do this'],plan)+snote('No edit can guarantee copyright clearance. Speed changes, pitch shifts, metadata changes or hidden audio code do not create permission and are not a detector bypass. Use original/licensed material, permission, or a defensible legal exception and keep records.');}
 if(id==='title-score'){const checks=[['Length between 30 and 70 characters',q.length>=30&&q.length<=70],['No repeated punctuation',!/[!?]{2,}/.test(q)],['No excessive uppercase words',q.split(/\s+/).filter(x=>/^[A-Z]{3,}$/.test(x)).length<=2],['No repeated words',new Set(q.toLowerCase().split(/\s+/)).size===q.split(/\s+/).length],['Readable word count (5–14)',q.split(/\s+/).length>=5&&q.split(/\s+/).length<=14]];data={score:checks.filter(x=>x[1]).length*20,checks};html=smetric('Heuristic score',data.score+'/100','Not a CTR prediction')+table(['Check','Result'],checks.map(([k,v])=>[k,v?'Pass':'Review']))}
 else if(id==='video-ids'){const rows=q.split(/[\s,]+/).filter(Boolean).map(x=>[x,extractVideo(x)||'Invalid URL / ID']);data={rows};html=table(['Input','Video ID'],rows)+'<button onclick="sdownload(\'video-ids.csv\',scsv(ST.result.rows),\'text/csv\')">Download CSV</button>'}
 else{const vid=extractVideo(q);if(!vid)throw Error('Enter a valid YouTube video URL or ID.');const seconds=['timestamp','embed'].includes(id)?Math.floor(sNumber('seconds')):0;const url='https://www.youtube.com/watch?v='+vid+(seconds?'&t='+seconds+'s':'');data={id:vid,url};if(id==='timestamp')html='<a href="'+sx(url)+'" target="_blank" rel="noopener">'+sx(url)+'</a>';else{const src='https://www.youtube-nocookie.com/embed/'+vid+'?start='+seconds;data.embed='<iframe width="560" height="315" src="'+src+'" title="YouTube video" allow="fullscreen" allowfullscreen></iframe>';html='<iframe style="width:100%;aspect-ratio:16/9;border:0" src="'+src+'" title="YouTube preview" allowfullscreen></iframe>'+(id==='frames'?snote('Pause the player, click inside it, then press comma (previous frame) or period (next frame). YouTube controls frame stepping; exact frame duration depends on the video.'):('<pre class="studio-output">'+sx(data.embed)+'</pre>'))}}
 return {...data,html,source:'Local utility'};}
async function loadImage(file){if(!file)throw Error('Choose an image first.');if(file.size>25*1024*1024)throw Error('Choose an image smaller than 25 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();return {img,url,file}}catch(e){URL.revokeObjectURL(url);throw Error('This image could not be decoded. Use PNG, JPEG or WebP.')}}
async function imageTool(t){const files=[...($('#sf-file').files||[])];if(!files.length)throw Error('Choose an image first.');if(t.mode==='preview'){if(files.length>3)throw Error('Choose at most three images.');for(const old of ST.previews)URL.revokeObjectURL(old.url);ST.previews=await Promise.all(files.map(loadImage));const title=svalue('q')||'Your video title';return {source:'Local feed preview',html:'<div class="studio-grid">'+ST.previews.map((v,i)=>'<div><img style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:10px" src="'+v.url+'" alt="Variant '+(i+1)+'"><h3 style="margin-top:12px">'+sx(title)+'</h3><p class="studio-muted">Your channel · Variant '+(i+1)+'</p></div>').join('')+'</div>',note:'A visual preview only. No invented CTR or view count; use your existing A/B hub to save and compare variants.'}}
 if(ST.image)URL.revokeObjectURL(ST.image.url);const v=await loadImage(files[0]);ST.image=v;const {img,file}=v;const isBanner=t.id==='banner';let html=table(['Property','Observed'],[['Dimensions',img.naturalWidth+' × '+img.naturalHeight],['Aspect ratio',(img.naturalWidth/img.naturalHeight).toFixed(3)],['File size',(file.size/1024/1024).toFixed(2)+' MB'],['Format',file.type],['16:9',Math.abs(img.naturalWidth/img.naturalHeight-16/9)<.02?'Yes':'No']]);html+='<div class="image-stage"><img src="'+v.url+'" alt="Selected image">'+(isBanner?'<div class="safe-area">Central 1546 × 423 safe area at 2560 × 1440</div>':'')+'</div>';
 if(t.id==='resize'||isBanner){const [w,h]=svalue('size').split('x').map(Number),fit=svalue('fit');const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#10141c';ctx.fillRect(0,0,w,h);const scale=fit==='cover'?Math.max(w/img.naturalWidth,h/img.naturalHeight):Math.min(w/img.naturalWidth,h/img.naturalHeight);ctx.drawImage(img,(w-img.naturalWidth*scale)/2,(h-img.naturalHeight*scale)/2,img.naturalWidth*scale,img.naturalHeight*scale);ST.image.canvas=canvas;html+='<button onclick="downloadStudioImage()">Download '+w+' × '+h+' PNG</button>';if(isBanner)html+='<button onclick="downloadBannerTemplate()">Download safe-area template</button>'}
 return {source:'Local image inspection',dimensions:[img.naturalWidth,img.naturalHeight],bytes:file.size,html,note:isBanner?'Safe-area overlay assumes a 16:9 banner. Resize first if your image has another aspect ratio.':'Dimensions are measured directly from your file. YouTube upload constraints may vary by surface; verify current upload requirements.'};}
function downloadStudioImage(){ST.image?.canvas?.toBlob(b=>{const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='clicklab-image.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)})}
function downloadBannerTemplate(){sdownload('banner-safe-area.svg','<svg xmlns="http://www.w3.org/2000/svg" width="2560" height="1440"><rect width="2560" height="1440" fill="#10141c"/><rect x="507" y="508.5" width="1546" height="423" fill="#213b35" stroke="#92edca" stroke-width="4"/><text x="1280" y="720" text-anchor="middle" fill="white" font-size="40">Text and logo safe area · 1546 × 423</text></svg>','image/svg+xml')}
function commentResults(t,r){return '<div class="studio-toolbar"><input id="comment-filter" aria-label="Filter loaded comments" placeholder="Search loaded comments" oninput="renderCommentRows()"><button onclick="moreComments()" '+(!r.next_page?'disabled':'')+'>Load next 100</button></div><p class="studio-muted">'+ST.comments.length+' top-level comments loaded'+(r.next_page?' · more available':' · end of current API listing')+'</p>'+(t.id==='picker'?'<label class="studio-check"><input id="comment-unique" type="checkbox" checked>One entry per author</label><button class="go" onclick="pickComment()">Draw from loaded matching comments</button><div id="comment-winner"></div>':'')+'<div id="comment-rows">'+table(['Author','Comment','Likes'],ST.comments.map(c=>[c.author,c.text,c.likes]))+'</div>'}
function filteredComments(){const q=($('#comment-filter')?.value||'').toLowerCase();return ST.comments.filter(c=>[c.text,c.author].join(' ').toLowerCase().includes(q))}
function renderCommentRows(){$('#comment-rows').innerHTML=table(['Author','Comment','Likes'],filteredComments().map(c=>[c.author,c.text,c.likes]))}
async function moreComments(){if(ST.busy||!ST.result.next_page)return;ST.busy=true;try{const r=await jp('/api/studio/tool',{kind:'comments',q:svalue('q'),page:ST.result.next_page});if(r.error)throw Error(r.error);const seen=new Set(ST.comments.map(c=>c.id));ST.comments.push(...r.rows.filter(c=>!seen.has(c.id)));ST.result={...r,rows:ST.comments};renderToolResult(STUDIO_TOOLS.find(t=>t.id===ST.tool),ST.result)}catch(e){toast(e.message,'bad')}finally{ST.busy=false}}
function pickComment(){let rows=filteredComments();if($('#comment-unique')?.checked)rows=[...new Map(rows.map(c=>[c.author_id||c.author,c])).values()];if(!rows.length)return toast('No eligible comments loaded','warn');const a=new Uint32Array(1);const limit=Math.floor(4294967296/rows.length)*rows.length;do{crypto.getRandomValues(a)}while(a[0]>=limit);const win=rows[a[0]%rows.length];ST.result.draw={winner:win,eligible:rows.length,at:new Date().toISOString()};$('#comment-winner').innerHTML=snote('Drawn from '+rows.length+' loaded eligible authors/comments at '+ST.result.draw.at)+table(['Winner','Comment'],[[win.author,win.text]])}
function renderChecklist(){const labels=['Correct payee name and address','Identity verification completed','Address PIN verification completed','Tax information submitted where required','Payment method added and verified','No payment holds shown in AdSense','Account currency payment threshold reached','Payment schedule checked in your AdSense account'];let state=[];try{state=JSON.parse(localStorage.getItem('cl_adsense_checklist')||'[]')}catch(e){}$('#tool-result').innerHTML=labels.map((l,i)=>'<label class="studio-check"><input type="checkbox" data-check="'+i+'" '+(state.includes(i)?'checked':'')+' onchange="saveChecklist()">'+sx(l)+'</label>').join('')+snote('Self-reported checklist. ClickLab does not access your AdSense account or verify payment eligibility.');ST.result={source:'Local checklist',items:labels,checked:state}}
function saveChecklist(){const checked=[...document.querySelectorAll('[data-check]:checked')].map(e=>Number(e.dataset.check));localStorage.setItem('cl_adsense_checklist',JSON.stringify(checked));ST.result.checked=checked}
function mountBetter2Preset(){const h=[...document.querySelectorAll('h4')].find(e=>e.textContent.includes('Better Polish preset'));if(!h||$('#sf-preset'))return;h.textContent='Better 2.0 / Better Polish presets';const p=h.parentElement;const desc=p.querySelector('p.studio-muted');if(desc)desc.textContent='Better 2.0 randomized studio mastering: per-file speed, pitch, crop, rotation, EQ and GOP values with metadata cleanup, grain, vignette and NVENC fallback. Use owned or licensed media.';const label=document.createElement('label');label.textContent='Editing preset';const s=document.createElement('select');s.id='sf-preset';s.innerHTML='<option value="better2">Better 2.0 · randomized studio mastering</option><option value="better">Better Polish · fixed defaults</option>';label.appendChild(s);p.insertBefore(label,desc?.nextSibling||p.firstChild);const exec=document.createElement('label');exec.textContent='Processing location';const es=document.createElement('select');es.id='sf-execution';es.innerHTML='<option value="local">This PC · local FFmpeg</option><option value="modal">Modal cloud · T4 GPU (fast)</option>';exec.appendChild(es);p.insertBefore(exec,s.nextSibling);const urlLabel=document.createElement('label');urlLabel.textContent='Optional YouTube video link';const url=document.createElement('input');url.id='sf-youtube-url';url.type='url';url.placeholder='https://www.youtube.com/watch?v=...';urlLabel.appendChild(url);p.insertBefore(urlLabel,label)}
new MutationObserver(mountBetter2Preset).observe(document.body,{childList:true,subtree:true});
VW.verification={f:toolVerification,t:'Tool verification',i:'layers'};
async function toolVerification(){const token=RTN;$('#main').innerHTML='<h1>Tool verification & feature gaps</h1>'+sempty('Reading verification evidence','Loading the latest local test report. No paid AI request is made.');try{const r=await jp('/api/studio/tool',{kind:'verification'});if(token!==RTN)return;$('#main').innerHTML='<h1>Tool verification & feature gaps</h1>'+snote(r.note||'Only the checks listed here were verified. A working input screen is not proof of a successful provider request.')+'<p class="studio-muted">'+sx(r.verified_at||'No test date recorded')+'</p>'+table(['Tool','Status','What was tested','TubeMind parity limits'],(r.tools||[]).map(t=>[t.name,t.status,t.evidence,t.parity_limits||'']))+'<button onclick="go(\'tools\')">Back to tools</button>'}catch(e){if(token===RTN)$('#main').innerHTML='<h1>Tool verification</h1><p role="alert">'+sx(e.message)+'</p>'}}
function decorateBetterDownload(r){const b=$('#better-download');if(!b||!r.output_token)return;const sel=document.createElement('select');sel.id='better-download-quality';sel.innerHTML=['1080','720','480'].map(q=>'<option value="'+q+'">'+q+'p download</option>').join('');sel.style.margin='0 8px 12px 0';b.parentNode.insertBefore(sel,b);b.onclick=()=>{const q=sel.value,source=q===(r.quality||'1080')?'/api/media-preview?token='+encodeURIComponent(r.output_token):'/api/better-download?token='+encodeURIComponent(r.output_token)+'&quality='+q;b.textContent='Preparing '+q+'p…';const a=document.createElement('a');a.href=source;a.download=r.name||'better.mp4';a.click();setTimeout(()=>b.textContent='Download '+(r.name||'better.mp4'),700)}}
async function runModalBetterEdit(base){
 betterProgress(2);
 const started=await jp('/api/modal-edit',base);if(started.error)throw Error(started.error);const job=started.job;
 const stop=document.createElement('button');stop.type='button';stop.className='sm gh';stop.textContent='Stop Modal job';stop.onclick=()=>{jp('/api/modal-cancel',{job}).catch(()=>{});stop.disabled=true;stop.textContent='Stopping…'};$('#tool-run')?.parentElement.appendChild(stop);
 for(;;){await new Promise(r=>setTimeout(r,1200));const pr=await fetch('/api/modal-progress?id='+encodeURIComponent(job));const p=await pr.json();if(!pr.ok)throw Error(p.error||pr.status);if(p.state==='error')throw Error(p.error||'Modal worker failed.');if(p.state==='cancelled')throw Error('Modal job stopped.');if(p.state==='done'){stop.remove();const r=p.result;if(r.output_token)BETTER_MEDIA.output='/api/media-preview?token='+encodeURIComponent(r.output_token);betterProgress(4);setTimeout(()=>decorateBetterDownload(r),0);return r}betterProgress(p.done>=45?3:1)}
}
async function showModalAccount(){const e=$('#sf-execution');if(!e||$('#sf-modal-status'))return;const p=document.createElement('p');p.id='sf-modal-status';p.className='studio-muted';p.textContent='Checking Modal account…';e.parentElement.appendChild(p);try{const r=await jp('/api/modal-status');p.textContent=r.connected?'Modal connected: '+r.profile+' · one active profile':'Modal not connected: '+(r.message||'login required')}catch(x){p.textContent='Modal status unavailable'}}
new MutationObserver(showModalAccount).observe(document.body,{childList:true,subtree:true});
function renderTopicCategories(key){const p=TOPIC_PRESETS[key],el=$('#topic-categories');if(!p||!el)return;el.innerHTML='<label>Category</label><div class="studio-chips">'+Object.entries(p.categories).map(([k,v])=>'<button type="button" class="chip" data-topic-category="'+k+'" onclick="selectTopicCategory(this.dataset.topicCategory)">'+sx(k.replaceAll('-',' '))+'</button>').join('')+'</div>'}
function renderTopicSubniches(key,category){const p=TOPIC_PRESETS[key],el=$('#topic-subniches'),items=p?.categories?.[category]||[];if(!el)return;el.innerHTML=items.length?'<label>15 sub-niches</label><div class="studio-chips">'+items.map(x=>'<button type="button" class="chip" data-topic-subniche="'+sx(x)+'" onclick="selectTopicSubniche(this.dataset.topicSubniche)">'+sx(x)+'</button>').join('')+'</div>':''}
function selectTopicSubniche(value){const hidden=$('#sf-subniche'),q=$('#sf-q');if(hidden)hidden.value=value;if(q)q.value=value;document.querySelectorAll('[data-topic-subniche]').forEach(b=>b.classList.toggle('on',b.dataset.topicSubniche===value));}
function selectTopicCategory(value){const cat=$('#sf-category'),sub=$('#sf-subniche'),q=$('#sf-q'),key=$('#sf-preset')?.value;if(cat)cat.value=value;if(sub)sub.value='';if(q)q.value='';document.querySelectorAll('[data-topic-category]').forEach(b=>b.classList.toggle('on',b.dataset.topicCategory===value));renderTopicSubniches(key,value);}
function selectTopicPreset(key){const p=TOPIC_PRESETS[key];if(!p)return;const hidden=$('#sf-preset'),cat=$('#sf-category'),sub=$('#sf-subniche'),q=$('#sf-q');if(hidden)hidden.value=key;if(cat)cat.value='';if(sub)sub.value='';if(q)q.value='';document.querySelectorAll('[data-topic-preset]').forEach(b=>b.classList.toggle('on',b.dataset.topicPreset===key));renderTopicCategories(key);if($('#topic-subniches'))$('#topic-subniches').innerHTML='';}
